              >
                <div className="sticky top-0 z-[2] flex h-9 items-center border-b border-white/10 bg-[#0a0a0e]/95 px-2 text-[11px] font-medium uppercase tracking-wide text-white/45 backdrop-blur-sm">
                  <span className="w-20 shrink-0 text-right tabular-nums">
                    Strike
                  </span>
                  <span className="mx-2 flex-1 text-center normal-case tracking-normal">
                    {valueMode === "gex_abs" ? (
                      <span className="text-sky-400/90">Absolute GEX →</span>
                    ) : valueMode === "gex_net" ? (
                      <span className="text-emerald-400/90">
                        ← Neg · Net · Pos →
                      </span>
                    ) : (
                      <span>
                        <span className="text-red-400/90">← Puts</span>
                        <span className="text-white/35"> · </span>
                        <span className="text-sky-400/90">Calls →</span>
                      </span>
                    )}
                  </span>
                  <span className="w-[4.5rem] shrink-0 text-right tabular-nums">
                    {valueMode === "gex_all" ||
                    valueMode === "gex_call" ||
                    valueMode === "gex_put"
                      ? "C / P"
                      : "Value"}
                  </span>
                </div>
                {gexProfile.points.map((pt) => {
                  const scale = smoothGexScale;
                  const combined =
                    valueMode === "gex_all" ||
                    valueMode === "gex_call" ||
                    valueMode === "gex_put";

                  // Animated magnitudes (lerp toward live GEX)
                  const callMag =
                    pt.call != null
                      ? (smoothGex[`${pt.strike}:c`] ?? Math.abs(pt.call))
                      : null;
                  const putMag =
                    pt.put != null
                      ? (smoothGex[`${pt.strike}:p`] ?? Math.abs(pt.put))
                      : null;
                  const callPct =
                    callMag != null
                      ? `${(Math.min(1, callMag / scale) * 50).toFixed(2)}%`
                      : "0%";
                  const putPct =
                    putMag != null
                      ? `${(Math.min(1, putMag / scale) * 50).toFixed(2)}%`
                      : "0%";

                  // Net / Abs single bar (value signed; abs mode uses magnitude)
                  const seriesRaw =
                    pt.valid && pt.value != null
                      ? (smoothGex[`${pt.strike}:v`] ?? pt.value)
                      : 0;
                  const seriesSigned =
                    valueMode === "gex_abs" ? Math.abs(seriesRaw) : seriesRaw;
                  const seriesFrac = Math.min(
                    1,
                    Math.abs(seriesSigned) / scale,
                  );
                  const seriesPct = `${(seriesFrac * 50).toFixed(2)}%`;
                  const seriesNeg = seriesSigned < 0;
                  const seriesPos = seriesSigned > 0;

                  const gexModel = heatmapGexTip({
                    strikeLabel: pt.label,
                    isSpot: pt.isSpot,
                    combined,
                    call: pt.call,
                    put: pt.put,
                    net: pt.value,
                    callLabel:
                      pt.call != null ? fmtGexProfile(pt.call) : "—",
                    putLabel: pt.put != null ? fmtGexProfile(pt.put) : "—",
                    netLabel:
                      pt.value != null ? fmtGexProfile(pt.value) : "—",
                  });

                  return (
                    <div
                      key={pt.strike}
                      data-spot={pt.isSpot ? "1" : "0"}
                      className={[
                        "flex h-8 items-center border-b border-white/[0.04] px-2",
                        pt.isSpot
                          ? "border-t border-amber-400/70 bg-amber-400/5"
                          : "",
                      ].join(" ")}
                      onMouseEnter={(e) => {
                        if (tipPinnedRef.current) return;
                        setHoverTip({
                          model: gexModel,
                          x: e.clientX,
                          y: e.clientY,
                        });
                      }}
                      onMouseLeave={() => {
                        if (tipPinnedRef.current) return;
                        setHoverTip(null);
                      }}
                    >
                      <span
                        className={[
                          "w-20 shrink-0 text-right tabular-nums font-medium",
                          pt.isSpot
                            ? "font-bold text-amber-400"
                            : "text-white/50",
                        ].join(" ")}
                      >
                        {pt.label}
                      </span>
                      <div className="relative mx-2 h-5 flex-1 overflow-hidden rounded-sm bg-white/[0.04]">
                        <div
                          className="absolute inset-y-0 left-1/2 w-px bg-white/25"
                          aria-hidden
                        />
                        {combined ? (
                          <>
                            {/* Put → left (red) */}
                            {putMag != null && putMag > 0 ? (
                              <div
                                className="absolute top-0.5 bottom-0.5 rounded-sm bg-red-500/85 motion-safe:transition-[width] motion-safe:duration-300 motion-safe:ease-out"
                                style={{ right: "50%", width: putPct }}
                              />
                            ) : null}
                            {/* Call → right (blue) */}
                            {callMag != null && callMag > 0 ? (
                              <div
                                className="absolute top-0.5 bottom-0.5 rounded-sm bg-sky-500/85 motion-safe:transition-[width] motion-safe:duration-300 motion-safe:ease-out"
                                style={{ left: "50%", width: callPct }}
                              />
                            ) : null}
                          </>
                        ) : pt.valid && (seriesPos || seriesNeg) ? (
                          <div
                            className={[
                              "absolute top-0.5 bottom-0.5 rounded-sm motion-safe:transition-[width,left,right] motion-safe:duration-300 motion-safe:ease-out",
                              valueMode === "gex_abs"
                                ? "bg-sky-500/90"
                                : seriesNeg
                                  ? "bg-red-500/85"
                                  : "bg-sky-500/85",
                            ].join(" ")}
                            style={
                              seriesNeg
                                ? { right: "50%", width: seriesPct }
                                : { left: "50%", width: seriesPct }
                            }
                          />
                        ) : null}
                      </div>
                      <span className="w-[4.5rem] shrink-0 text-right tabular-nums text-[11px] leading-tight">
                        {combined ? (
                          <>
                            <span className="text-sky-400">
                              {callMag != null ? fmtGexProfile(callMag) : "—"}
                            </span>
                            <span className="text-white/30">/</span>
                            <span className="text-red-400">
                              {putMag != null ? fmtGexProfile(putMag) : "—"}
                            </span>
                          </>
                        ) : (
                          <span
                            className={
                              !pt.valid
                                ? "text-white/25"
                                : seriesNeg
                                  ? "text-red-400"
                                  : "text-sky-400"
                            }
                          >
                            {pt.valid && pt.value != null
                              ? fmtGexProfile(seriesRaw)
                              : "—"}
                          </span>
                        )}
                      </span>
                    </div>
                  );
                })}
                {!gexProfile.points.length && (
                  <div className="px-4 py-24 text-center text-white/40">
                    {expiration
                      ? "Waiting for dual-side chain (γ / OI)…"
                      : "Choose a contract"}
                  </div>
                )}
              </div>

gexFrozenSrc:
/**
 * Chain GEX estimate — vertical profile (strike axis), Spec §5.5 / MSC-style.
 *
 * Value modes:
 *   - Combined (default): call bar → right, put bar → left on same strike
 *   - Net: single signed bar
 *   - Absolute: |call|+|put| → right
 *
 * Formula gex_v1: call +Γ·OI·S² ; put −Γ·OI·S² ; net = sum ; abs = |C|+|P|
 */

import type { ChainContext, HeatmapTemplate, ValueModeId } from "./types";
import { contractKey } from "@/lib/chainLadderApi";
import { gexAbs, gexNet, gexSide } from "./pricing";

export type GexProfilePoint = {
  strike: number;
  label: string;
  isSpot: boolean;
  /** Mode series value (net / abs / or null when combined-only) */
  value: number | null;
  valid: boolean;
  call: number | null;
  put: number | null;
};

/**
 * Listed expiration for Analyzer GEX. Chain-attached (AZ-VP-2): not a
 * position book. Prefer a shown card’s exp, else Range horizon, else first
 * listed. Empty / hidden book still has a horizon.
 */
export function gexHorizonExpiration(opts: {
  tradeExpiration?: string | null;
  rangeHorizon?: string | null;
  listedExpirations?: readonly string[] | null;
}): string {
  const listed = (opts.listedExpirations ?? [])
    .map((e) => (e || "").slice(0, 10))
    .filter((e) => /^\d{4}-\d{2}-\d{2}$/.test(e));
  const candidates = [
    (opts.tradeExpiration || "").slice(0, 10),
    (opts.rangeHorizon || "").slice(0, 10),
    ...listed,
  ];
  return candidates.find((e) => /^\d{4}-\d{2}-\d{2}$/.test(e)) ?? "";
}

export function buildGexProfile(
  ctx: ChainContext,
  mode: ValueModeId,
): GexProfilePoint[] {
  const strikes = new Set<number>();
  for (const row of ctx.contracts.values()) {
    strikes.add(Number(row.strike));
  }
  const sorted = [...strikes].sort((a, b) => b - a);
  return sorted.map((k) => {
    const cRow = ctx.contracts.get(contractKey("call", k));
    const pRow = ctx.contracts.get(contractKey("put", k));
    const call = gexSide(ctx, "call", k);
    const put = gexSide(ctx, "put", k);

    let value: number | null = null;
    let valid = false;

    switch (mode) {
      case "gex_abs":
        value = gexAbs(ctx, k);
        valid = value != null;
        break;
      case "gex_net":
        value = gexNet(ctx, k);
        valid = value != null;
        break;
      case "gex_all": // combined book view
      case "gex_call": // legacy → treat as combined
      case "gex_put":
      default:
        // Combined: valid if either side has data
        valid = call != null || put != null;
        value = gexNet(ctx, k); // still compute net for label/tooltip when both present
        break;
    }

    return {
      strike: k,
      label: String(k),
      isSpot: Boolean(cRow?.is_spot || pRow?.is_spot),
      value,
      valid,
      call,
      put,
    };
  });
}

function peakOf(vals: number[]): number {
  let peak = 0;
  for (const v of vals) {
    if (v > peak) peak = v;
  }
  return peak || 1;
}

/** Longest-bar scale — mode-aware. Peak magnitude maps to full bar length. */
export function gexProfileScale(
  points: GexProfilePoint[],
  mode: ValueModeId,
): number {
  const vals: number[] = [];
  for (const p of points) {
    if (mode === "gex_abs") {
      if (p.valid && p.value != null) vals.push(Math.abs(p.value));
    } else if (mode === "gex_net") {
      if (p.valid && p.value != null) vals.push(Math.abs(p.value));
    } else {
      if (p.call != null) vals.push(Math.abs(p.call));
      if (p.put != null) vals.push(Math.abs(p.put));
    }
  }
  return peakOf(vals);
}

/** Combined Call/Put: each side has its own longest-bar peak. */
export function gexSidePeaks(points: GexProfilePoint[]): {
  call: number;
  put: number;
  hasCall: boolean;
  hasPut: boolean;
} {
  const calls: number[] = [];
  const puts: number[] = [];
  for (const p of points) {
    if (p.call != null) calls.push(Math.abs(p.call));
    if (p.put != null) puts.push(Math.abs(p.put));
  }
  return {
    call: peakOf(calls),
    put: peakOf(puts),
    hasCall: calls.length > 0,
    hasPut: puts.length > 0,
  };
}

export const GEX_DISPLAY_DIV = 1e9;

export function fmtGexProfile(n: number): string {
  const v = n / GEX_DISPLAY_DIV;
  return v.toLocaleString(undefined, {
    maximumFractionDigits: 2,
    minimumFractionDigits: 0,
  });
}

/** Compact right-axis label. Same ÷1e9 units as heatmap GEX. */
export function fmtGexAxis(raw: number): string {
  if (!Number.isFinite(raw) || Math.abs(raw) < 1e-18) return "0";
  const v = raw / GEX_DISPLAY_DIV;
  const abs = Math.abs(v);
  const digits = abs >= 100 ? 0 : abs >= 10 ? 1 : 2;
  const body = abs.toLocaleString(undefined, {
    maximumFractionDigits: digits,
    minimumFractionDigits: 0,
  });
  return v < 0 ? `−${body}` : body;
}

/**
 * GEX value → plot Y. 0 sits at mid-height; +peak at the top edge, −peak at the bottom.
 * Bars and the right scale must use this same mapping.
 */
export function gexValueToPlotY(
  value: number,
  peak: number,
  plotTop: number,
  plotHeight: number,
): number {
  const maxH = Math.max(1, plotHeight / 2);
  const axisY = plotTop + plotHeight / 2;
  const p = Math.max(Math.abs(peak), 1e-12);
  return axisY - (value / p) * maxH;
}

export const gexTemplate: HeatmapTemplate = {
  id: "gex",
  label: "GEX (traditional)",
  description:
    "Vertical profile · Call+Put combined · Net · Absolute · Γ×OI×S² · not dealer GEX",
  layout: "profile",
  valueModes: [
    { id: "gex_all", label: "Call / Put" },
    { id: "gex_net", label: "Net" },
    { id: "gex_abs", label: "Absolute" },
  ],
  defaultValueMode: "gex_all",

  resolveColumns: () => [],
  resolveRows: () => [],
  computeCell: () => ({ display: null, value: null, valid: false }),
  assignColors: () => ({ stickyScale: 1 }),
};
